function toast(msg, kind = "") {
  const t = document.createElement("div");
  t.className = "toast" + (kind ? " toast--" + kind : "");
  t.innerHTML = msg;
  $("#toastStack").appendChild(t);
  setTimeout(() => { t.classList.add("out"); setTimeout(() => t.remove(), 450); }, 3400);
}
function fmt(n) { return CONFIG.currency + Number(n).toFixed(2); }
function escapeHtml(s) { return String(s).replace(/[&<>"']/g, (c) =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
/* Firestore hands timestamps back as Timestamp objects; sessions written in
   this tab still hold plain numbers. One reader for both. */
function asDate(v) {
  if (!v) return new Date();
  if (typeof v === "number") return new Date(v);
  if (v instanceof Date) return v;
  if (typeof v.toDate === "function") return v.toDate();
  if (typeof v.seconds === "number") return new Date(v.seconds * 1000);
  return new Date(v);
}
const now = () => Date.now();
/* the same value as a number, for cache keys and cheap change-detection —
   asDate() allocates a Date on every call and these run per session, per pass */
function asMs(v) {
  if (!v) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "object") {
    if (typeof v.seconds === "number") return v.seconds * 1000;
    if (typeof v.getTime === "function") return v.getTime();
    if (typeof v.toDate === "function") { try { return v.toDate().getTime(); } catch (e) { return 0; } }
  }
  const t = new Date(v).getTime();
  return t === t ? t : 0;
}
