  if (!it.r && fx > 0 && fy > 0) return [x, y];
  const bb = mkBBox(it), cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
  const dx = (x - cx) * fx, dy = (y - cy) * fy;
