    if (over < Math.min(c1 - c0, d1 - d0) * 0.4) return;
    if (bl + bs <= lo && (!before || bl + bs > (horiz ? before.x + before.w : before.y + before.h))) before = b;
    if (bl >= hi && (!after || bl < (horiz ? after.x : after.y))) after = b;
