      if (c <= 0x20 || c === 0) continue;                 /* whitespace */
      if (c === 0x7a && n === 0) { out.push(0, 0, 0, 0); continue; }   /* z */
      if (c < 0x21 || c > 0x75) continue;                 /* not base-85 */
      tuple = tuple * 85 + (c - 0x21); n++;
